using Netgum.Application.Abstractions;
using Netgum.Domain.Orders;

namespace Netgum.Api.Endpoints;

public static class OrderEndpoints
{
    public static IEndpointRouteBuilder MapOrderEndpoints(this IEndpointRouteBuilder app)
    {
        var group = app.MapGroup("/api/orders").WithTags("Orders");

        group.MapGet("/{orderId:guid}/download", async (
            Guid orderId,
            IOrderRepository orders,
            CancellationToken cancellationToken) =>
        {
            var order = await orders.GetByIdAsync(orderId, cancellationToken).ConfigureAwait(false);
            if (order is null)
            {
                return Results.NotFound();
            }

            if (order.PaymentStatus != PaymentStatus.Paid)
            {
                return Results.Problem("Order has not been paid.", statusCode: StatusCodes.Status403Forbidden);
            }

            return Results.Ok(new
            {
                order.Id,
                DownloadUrl = $"https://files.example.test/downloads/{order.ProductId}?license={order.LicenseKey}",
                order.LicenseKey
            });
        })
        .WithName("DownloadOrder")
        .WithOpenApi();

        return app;
    }
}

// BootQuest kata module: a TESTABLE, self-contained adaptation (not a repo file) of netgum @ 2984d9b:
//   src/Netgum.Api/Endpoints/OrderEndpoints.cs:12-34 (the GET /api/orders/{orderId}/download handler, verbatim body),
//   src/Netgum.Api/Program.cs:47-68 (UseExceptionHandler: the status for an exception that escapes an endpoint) and
//   src/Netgum.Domain/Abstractions/DomainException.cs.
// Minimal-API plumbing (Results, StatusCodes, the repository) is replaced by plain stand-ins so the flow
// compiles on its own; the handler body and the exception -> status switch are copied verbatim.
namespace Netgum.Kata;

public sealed class DomainException : Exception
{
    public DomainException(string message)
        : base(message)
    {
    }
}

public enum PaymentStatus
{
    Pending,
    Paid,
}

public sealed record Order(Guid Id, Guid ProductId, string LicenseKey, PaymentStatus PaymentStatus);

public interface IOrderRepository
{
    Task<Order?> GetByIdAsync(Guid orderId, CancellationToken cancellationToken);
}

public sealed record HttpResult(int StatusCode, string? Detail = null, object? Value = null);

public static class StatusCodes
{
    public const int Status400BadRequest = 400;
    public const int Status403Forbidden = 403;
    public const int Status404NotFound = 404;
    public const int Status409Conflict = 409;
    public const int Status500InternalServerError = 500;
}

public static class Results
{
    public static HttpResult NotFound() => new(StatusCodes.Status404NotFound);

    public static HttpResult Problem(string detail, int statusCode) => new(statusCode, detail);

    public static HttpResult Ok(object value) => new(200, null, value);
}

public static class OrderEndpoints
{
    /// <summary>The DownloadOrder route handler (MapGet "/{orderId:guid}/download").</summary>
    public static readonly Func<Guid, IOrderRepository, CancellationToken, Task<HttpResult>> DownloadOrder = async (
            Guid orderId,
            IOrderRepository orders,
            CancellationToken cancellationToken) =>
        {
            var order = await orders.GetByIdAsync(orderId, cancellationToken).ConfigureAwait(false);
            if (order is null)
            {
                return Results.NotFound();
            }

            if (order.PaymentStatus != PaymentStatus.Paid)
            {
                return Results.Problem("Order has not been paid.", statusCode: StatusCodes.Status403Forbidden);
            }

            return Results.Ok(new
            {
                order.Id,
                DownloadUrl = $"https://files.example.test/downloads/{order.ProductId}?license={order.LicenseKey}",
                order.LicenseKey
            });
        };
}

/// <summary>The global exception handler: what the client sees when an endpoint throws.</summary>
public static class ExceptionHandler
{
    public static (int Status, string Title) Map(Exception? exception)
    {
        var (status, title) = exception switch
        {
            DomainException => (StatusCodes.Status400BadRequest, "Business rule violation"),
            InvalidOperationException => (StatusCodes.Status409Conflict, "Invalid operation"),
            _ => (StatusCodes.Status500InternalServerError, "Unexpected server error")
        };

        return (status, title);
    }

    /// <summary>Run an endpoint the way the pipeline does: its result, or the mapped status of what it threw.</summary>
    public static async Task<int> StatusOf(Func<Task<HttpResult>> endpoint)
    {
        try
        {
            return (await endpoint().ConfigureAwait(false)).StatusCode;
        }
        catch (Exception exception)
        {
            return Map(exception).Status;
        }
    }
}

