using Netgum.Kata;

// netgum has no endpoint tests upstream (tests/Netgum.Tests covers the domain + CheckoutService only):
// these pin the behavior review finding A (astraupskill/06-SOLUTIONS-AND-REVIEW.md:108) depends on.
public sealed class OrderDownloadTests
{
    private sealed class Repo(params Order[] orders) : IOrderRepository
    {
        public Task<Order?> GetByIdAsync(Guid orderId, CancellationToken cancellationToken) =>
            Task.FromResult(orders.FirstOrDefault(o => o.Id == orderId));
    }

    [Fact(DisplayName = "download of an unknown order id answers 404, not 400 (review finding A, astraupskill/06-SOLUTIONS-AND-REVIEW.md:108)")]
    public async Task UnknownOrder_Is404()
    {
        var status = await ExceptionHandler.StatusOf(() => OrderEndpoints.DownloadOrder(Guid.NewGuid(), new Repo(), CancellationToken.None));

        Assert.Equal(404, status);
    }

    [Fact(DisplayName = "a paid order downloads (200) with its license key in the link")]
    public async Task PaidOrder_Downloads()
    {
        var order = new Order(Guid.NewGuid(), Guid.NewGuid(), "LIC-123", PaymentStatus.Paid);

        var result = await OrderEndpoints.DownloadOrder(order.Id, new Repo(order), CancellationToken.None);

        Assert.Equal(200, result.StatusCode);
        Assert.Contains("license=LIC-123", result.Value!.GetType().GetProperty("DownloadUrl")!.GetValue(result.Value) as string);
    }

    [Fact(DisplayName = "an unpaid order is refused with 403")]
    public async Task UnpaidOrder_Is403()
    {
        var order = new Order(Guid.NewGuid(), Guid.NewGuid(), "LIC-9", PaymentStatus.Pending);

        Assert.Equal(403, await ExceptionHandler.StatusOf(() => OrderEndpoints.DownloadOrder(order.Id, new Repo(order), CancellationToken.None)));
    }

    [Fact(DisplayName = "a DomainException is a 400 'Business rule violation' (src/Netgum.Api/Program.cs:54)")]
    public void DomainException_Is400()
    {
        Assert.Equal((400, "Business rule violation"), ExceptionHandler.Map(new DomainException("rule")));
    }
}
